{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "In rat PK, the closest analogue (12b) showed minimal brain exposure (AUC0-8 104 ng·h/g) after oral dosing, directly supporting poor CNS access for the query's triazine/aminopyridine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The closely related analogue 7b was impermeable across the BBB in rat PK, with minimal brain levels, reinforcing the poor-penetration phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "SB2602, which shares the aminopyridine and bridged morpholine-triazine motif, had limited brain access (brain/plasma ~1:5.6) in rats.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "CLR457, a related heteroaromatic amine, had a brain/plasma AUC ratio of 0.07, indicating minimal CNS penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "GNE-049 had Kpuu 0.43 and was considered permeable enough to cause CNS signs, providing a contradictory moderate-access data point, but its lower similarity and different scaffold limit transfer.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query's high TPSA/HBA and triazine/bridged-morpholine architecture align with multiple direct rat PK/BBB measurements showing poor brain penetration; the closest analogues are consistently CNS-impermeable. Occasional permeable analogues are structurally distant and do not override the dominant fail evidence.",
  "evidence_gaps": [
    "No direct query-specific BBB data are available.",
    "All evidence analogues have low Morgan similarity (<0.31), limiting quantitative transfer.",
    "No transporter/efflux assay data for the query itself.",
    "Only one moderate-access analogue (Kpuu 0.43) provides a partial contradictory signal."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

